insert into passages (id, text, difficulty_level, b, active) values
('5ff616b3-1c05-4733-828a-cc61038b3d7f', 'Bees communicate the location of food sources to other members of their hive through an intricate series of movements known as the waggle dance. First described in detail by Austrian scientist Karl von Frisch, whose research later earned him a Nobel Prize, the dance encodes both the direction and the distance of a food source relative to the hive and the sun. A bee performing the dance moves in a figure-eight pattern, with the straight middle portion of the pattern, known as the waggle run, indicating direction: the angle of the waggle run relative to vertical corresponds to the angle between the food source and the sun. The duration of the waggle run correlates with distance, so a longer run signals a food source that is farther away. Remarkably, bees are able to adjust their dances throughout the day to account for the sun''s changing position in the sky, and can even continue communicating accurate directions on cloudy days by using patterns of polarized light that remain detectable even when the sun itself is hidden behind clouds. Researchers continue to study additional aspects of the dance, including how successfully other bees interpret and act on the information conveyed.', 2, -1.0, true);
insert into questions (id, type, text, passage_id, options, correct_answer, explanation, a, b, c, difficulty_level, created_by, hint, active) values
('f7cb040c-fbbd-4819-a042-5277a247ffef', 'sentence_completion', 'By the time the ambulance arrived, the paramedics ___ already the situation over the phone.', NULL, '[{"id": "a", "text": "had assessed"}, {"id": "b", "text": "assess"}, {"id": "d", "text": "have assessed"}, {"id": "c", "text": "assessed"}]'::jsonb, 0, '{"strategy": "By the time...arrived...already = בזמן שהגיעה...כבר. פעולה שהושלמה לפני פעולה אחרת בעבר = past perfect.", "correct_reason": "had assessed = כבר העריכו. had + assessed מציין פעולה שהושלמה לפני הגעת האמבולנס.", "options_analysis": ["נכון! had assessed = past perfect, מתאים לפעולה שהושלמה לפני הגעה", "assess = הווה — לא מתאים לעבר", "have assessed = הווה מושלם — לא מתאים ל''By the time...arrived'' שמרמז עבר", "assessed = עבר פשוט — פחות מדגיש השלמה לפני אירוע אחר"]}', 0.99, -1.0, 0.25, 2, 'ai', NULL, true),
('67290d37-2166-4a35-bfba-78cca961049a', 'sentence_completion', 'The students, several of ___ had never traveled abroad, were excited about the trip.', NULL, '[{"id": "b", "text": "them"}, {"id": "c", "text": "whom"}, {"id": "d", "text": "they"}, {"id": "a", "text": "who"}]'::jsonb, 1, '{"strategy": "several of + פסוקית זיקה = דורש כינוי אובייקט אחרי preposition. several of whom.", "correct_reason": "whom = מהם. אחרי preposition (of) בפסוקית זיקה משתמשים ב-whom.", "options_analysis": ["them = כינוי אובייקט רגיל — לא מתאים לפסוקית זיקה", "נכון! whom = כינוי זיקה לאחר preposition (of whom)", "they = כינוי גוף — לא מתאים אחרי preposition", "who = כינוי זיקה לנושא — לא מתאים אחרי preposition"]}', 1.12, -1.0, 0.25, 2, 'ai', NULL, true),
('75d20a00-84e0-47eb-af31-26a9b6f0bdde', 'sentence_completion', 'It is imperative that the medication ___ administered exactly as prescribed.', NULL, '[{"id": "a", "text": "was"}, {"id": "b", "text": "being"}, {"id": "d", "text": "be"}, {"id": "c", "text": "is"}]'::jsonb, 2, '{"strategy": "It is imperative that = הכרחי ש-. אחרי ביטויי הכרחיות בא subjunctive (צורת בסיס).", "correct_reason": "be = יהיה. imperative that + subject + base form (subjunctive).", "options_analysis": ["was = עבר — לא מתאים לתבנית subjunctive", "being = ing לא מתאים אחרי imperative that", "נכון! subjunctive: imperative that + subject + base form (be)", "is = הווה רגיל — לא מתאים ל-subjunctive"]}', 0.91, -1.0, 0.25, 2, 'ai', NULL, true),
('f977ae0f-4c8a-4d07-9c55-aa09794cd3d2', 'sentence_completion', 'Scarcely ___ the ceremony begun when a sudden downpour forced everyone inside.', NULL, '[{"id": "b", "text": "has"}, {"id": "c", "text": "did"}, {"id": "a", "text": "was"}, {"id": "d", "text": "had"}]'::jsonb, 3, '{"strategy": "Scarcely...when = בקושי...כש-. Scarcely + past perfect + when מציין רצף אירועים מהיר.", "correct_reason": "had = כבר. Scarcely had + past participle + when = תבנית תקנית.", "options_analysis": ["has לא מתאים לעבר — ''forced'' מרמז עבר", "did לא מתאים לתבנית Scarcely...when", "was לא מתאים ל-begun שדורש had", "נכון! Scarcely had + participle + when = תבנית תקנית לרצף מהיר"]}', 0.9, -1.0, 0.25, 2, 'ai', NULL, true),
('ddfac7ad-a8e4-4def-85fd-238685be1b21', 'sentence_completion', 'The board recommended that the proposal ___ reviewed by an independent committee.', NULL, '[{"id": "d", "text": "be"}, {"id": "c", "text": "was"}, {"id": "a", "text": "has been"}, {"id": "b", "text": "is"}]'::jsonb, 0, '{"strategy": "recommended that = המליץ ש-. אחרי recommend בא subjunctive (צורת בסיס).", "correct_reason": "be = יהיה. recommend that + subject + be (subjunctive).", "options_analysis": ["נכון! subjunctive: recommend that + subject + base form (be)", "עבר לא מתאים לתבנית subjunctive", "have been = הווה מושלם — לא מתאים ל-subjunctive", "is = הווה רגיל — לא מתאים ל-subjunctive אחרי recommend"]}', 0.87, -1.0, 0.25, 2, 'ai', NULL, true),
('c40370d1-3efd-48d7-929e-fc7bf2dd5224', 'sentence_completion', 'Had she ___ about the delay earlier, she would have made alternative arrangements.', NULL, '[{"id": "b", "text": "knows"}, {"id": "c", "text": "known"}, {"id": "d", "text": "know"}, {"id": "a", "text": "knowing"}]'::jsonb, 1, '{"strategy": "Had she known...would have = תבנית תנאי היפותטי הפוך (inversion) של ''If she had known''.", "correct_reason": "known = ידעה. Had + subject + past participle = תבנית תנאי סוג 3 בהיפוך.", "options_analysis": ["knows = הווה — לא מתאים לתנאי היפותטי בעבר", "נכון! Had + subject + past participle = תנאי סוג 3 בהיפוך", "know = צורת בסיס — לא מתאימה אחרי Had בתבנית זו", "knowing = ing לא מתאים אחרי Had בתבנית זו"]}', 0.85, -1.0, 0.25, 2, 'ai', NULL, true),
('ef0ad992-00ed-4499-a5dc-653e43b18939', 'sentence_completion', 'The proposal, the details of ___ remain confidential, will be presented next week.', NULL, '[{"id": "b", "text": "what"}, {"id": "a", "text": "it"}, {"id": "d", "text": "which"}, {"id": "c", "text": "that"}]'::jsonb, 2, '{"strategy": "the details of...remain confidential = הפרטים...נשארים סודיים. פסוקית זיקה על עצם (proposal), נדרש which אחרי preposition.", "correct_reason": "which = ש-. the details of which = תבנית זיקה תקנית לעצם.", "options_analysis": ["what לא כינוי זיקה תקני בהקשר זה", "it לא כינוי זיקה תקני כאן", "נכון! which מתאים לעצם אחרי preposition (of which)", "that לא משמש אחרי preposition כמו of"]}', 1.07, -1.0, 0.25, 2, 'ai', NULL, true),
('553bac4a-5e53-49a6-bf03-b456b72d8ad4', 'sentence_completion', 'Seldom ___ a performance received such universal acclaim from critics.', NULL, '[{"id": "a", "text": "do"}, {"id": "d", "text": "does"}, {"id": "c", "text": "did"}, {"id": "b", "text": "has"}]'::jsonb, 3, '{"strategy": "Seldom...= לעיתים נדירות. תבנית היפוך אחרי מילת תדירות נמוכה בתחילת משפט.", "correct_reason": "has = כבר. Seldom has + subject + participle = תבנית היפוך תקנית עם present perfect.", "options_analysis": ["do = רבים — לא מתאים למופע יחיד", "does לא מתאים לתבנית עם participle", "did לא מתאים לתבנית עם ''received'' כ-participle", "נכון! Seldom has + subject + participle = תבנית היפוך עם present perfect"]}', 1.03, -1.0, 0.25, 2, 'ai', NULL, true),
('132b1315-bce5-46a1-8844-bf91414f7b8c', 'sentence_completion', 'The manager was accused of ___ funds meant for employee bonuses.', NULL, '[{"id": "d", "text": "misappropriating"}, {"id": "a", "text": "misappropriated"}, {"id": "b", "text": "to misappropriate"}, {"id": "c", "text": "misappropriate"}]'::jsonb, 0, '{"strategy": "accused of = הואשם ב-. accuse of נדרש gerund (ing) כמושא.", "correct_reason": "misappropriating = לגזול/להשתמש שלא כדין. accuse of + gerund הוא תבנית תקנית.", "options_analysis": ["נכון! accused of + gerund (ing) = תבנית תקנית", "misappropriated = עבר — לא תקין כמושא ל-accused of", "to misappropriate = infinitive — accused of לא לוקח infinitive", "misappropriate לבד ללא ing לא תקין אחרי accused of"]}', 1.13, -1.0, 0.25, 2, 'ai', NULL, true),
('d4e77b72-4eed-48eb-9b55-5cb605d85b3b', 'sentence_completion', 'She is the only employee in the department ___ consistently exceeds sales targets.', NULL, '[{"id": "c", "text": "whose"}, {"id": "a", "text": "who"}, {"id": "d", "text": "whom"}, {"id": "b", "text": "which"}]'::jsonb, 1, '{"strategy": "the only employee...exceeds = העובדת היחידה...עוברת. פסוקית זיקה על אדם (employee) כנושא.", "correct_reason": "who = ש-. who משמש לתיאור אדם כנושא הפסוקית.", "options_analysis": ["whose מציין שייכות, לא מתאים כאן", "נכון! who = מתאים לאדם כנושא הפסוקית", "whom משמש למושא, לא לנושא הפסוקית", "which משמש לעצמים, לא לאנשים כמו employee"]}', 0.93, -1.0, 0.25, 2, 'ai', NULL, true),
('27196e5d-76bf-4f02-bccc-44073eddf3af', 'sentence_completion', 'Not until the results were published ___ the full extent of the problem.', NULL, '[{"id": "b", "text": "anyone realized"}, {"id": "d", "text": "realized anyone"}, {"id": "a", "text": "did anyone realize"}, {"id": "c", "text": "anyone did realize"}]'::jsonb, 2, '{"strategy": "Not until = לא עד ש-. תבנית שלילית בתחילת משפט דורשת היפוך.", "correct_reason": "did anyone realize = מישהו הבין. Not until + clause + did + subject + verb = היפוך תקני.", "options_analysis": ["חסר היפוך אחרי Not until בתחילת המשפט", "סדר מילים שגוי לגמרי", "נכון! Not until...did anyone realize = היפוך תקני", "סדר מילים שגוי — auxiliary כפול"]}', 0.93, -1.0, 0.25, 2, 'ai', NULL, true),
('8326ecb1-1758-4c5b-980e-046ee4dd5e17', 'sentence_completion', 'The director, together with the producers, ___ making final decisions about the film''s release date.', NULL, '[{"id": "a", "text": "are"}, {"id": "b", "text": "were"}, {"id": "c", "text": "have been"}, {"id": "d", "text": "is"}]'::jsonb, 3, '{"strategy": "together with = יחד עם. ''together with'' לא הופך את הנושא לרבים — הנושא הדקדוקי הוא the director ביחיד.", "correct_reason": "is = הוא. הנושא היחיד (director) קובע את הפועל, לא ''together with the producers''.", "options_analysis": ["are = רבים — לא מתאים כי ''together with'' לא הופך ל-director לרבים", "were = עבר רבים — לא מתאים לא לזמן ולא למספר", "have been = רבים — לא מתאים לנושא היחיד", "נכון! is = יחיד, מתאים ל''the director'' כנושא דקדוקי"]}', 0.79, -1.0, 0.25, 2, 'ai', NULL, true),
('ff24cca2-b94a-42bc-a273-7ba4445f1774', 'restatement', 'The lecture, despite being highly technical, managed to hold the audience''s attention throughout.', NULL, '[{"id": "c", "text": "Even though the lecture was very technical, it kept the audience engaged the whole time."}, {"id": "a", "text": "The lecture was simple and had no technical content."}, {"id": "b", "text": "The lecture failed to engage the audience because it was too technical."}, {"id": "d", "text": "No one attended the lecture."}]'::jsonb, 0, '{"strategy": "despite technical, held attention = למרות טכני, שמר על תשומת לב. ניגוד.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["נכון! אותה משמעות בדיוק: טכנית מאוד, אך שמרה על תשומת לב הקהל לאורך זמן", "הפוך — ''simple'' סותר ''highly technical''", "הפוך — סותר ''managed to hold the audience''s attention''", "סותר את קיום הקהל שתואר"]}', 1.03, -1.0, 0.25, 2, 'ai', NULL, true),
('39d2d36a-1497-49da-a6c6-72f78e3b7195', 'restatement', 'The organization''s funding, though reduced this year, still allows it to continue its core programs.', NULL, '[{"id": "b", "text": "The organization received more funding than ever this year."}, {"id": "d", "text": "Although the funding was cut this year, the organization can still run its main programs."}, {"id": "a", "text": "The organization was forced to stop all of its programs."}, {"id": "c", "text": "The organization has no funding at all."}]'::jsonb, 1, '{"strategy": "though reduced, still allows to continue = למרות הפחתה, עדיין מאפשר להמשיך.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["הפוך — ''more funding than ever'' סותר ''reduced this year''", "נכון! אותה משמעות בדיוק: הופחת השנה, אך עדיין מאפשר תוכניות ליבה", "הפוך — סותר ''still allows it to continue its core programs''", "סותר את קיום המימון שתואר כמופחת לא נעדר"]}', 0.76, -1.0, 0.25, 2, 'ai', NULL, true),
('fa2eb9d1-1c8a-489a-a284-099f7d9c3370', 'restatement', 'The city council approved the budget after making several last-minute amendments.', NULL, '[{"id": "d", "text": "The city council never voted on the budget."}, {"id": "a", "text": "The budget was approved with no changes made."}, {"id": "c", "text": "After making some final changes, the city council gave its approval to the budget."}, {"id": "b", "text": "The city council rejected the budget without any discussion."}]'::jsonb, 2, '{"strategy": "approved after making amendments = אישרה אחרי תיקונים. רצף.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["הפוך — סותר את קיום ההצבעה שתוארה", "סותר ''several last-minute amendments''", "נכון! אותה משמעות בדיוק: אחרי שינויים אחרונים, המועצה אישרה את התקציב", "הפוך — סותר ''approved the budget''"]}', 0.89, -1.0, 0.25, 2, 'ai', NULL, true),
('a14cd7aa-4bb0-4145-a9d6-823636cb69fc', 'restatement', 'The athlete''s recovery, slower than doctors initially expected, nonetheless proceeded without complications.', NULL, '[{"id": "d", "text": "The athlete''s recovery was faster than doctors had expected."}, {"id": "a", "text": "The athlete''s recovery was full of serious complications."}, {"id": "c", "text": "The athlete never recovered from the injury."}, {"id": "b", "text": "Although the recovery took longer than doctors first predicted, it happened without any problems."}]'::jsonb, 3, '{"strategy": "slower than expected, nonetheless without complications = ניגוד בין קצב לתוצאה.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["הפוך — ''faster'' סותר ''slower''", "הפוך — סותר ''without complications''", "סותר את קיום ההחלמה שתוארה", "נכון! אותה משמעות בדיוק: איטית מהצפוי, אך ללא סיבוכים"]}', 1.05, -1.0, 0.25, 2, 'ai', NULL, true),
('aa8393a4-aad7-4b41-bc2f-59e1ee1e6bbd', 'restatement', 'The company''s new hiring policy, aimed at increasing diversity, has drawn both praise and criticism.', NULL, '[{"id": "b", "text": "The policy, intended to boost diversity, has received mixed reactions of approval and disapproval."}, {"id": "c", "text": "The company has no hiring policy at all."}, {"id": "d", "text": "The hiring policy has received only praise from everyone."}, {"id": "a", "text": "The policy was designed to reduce diversity."}]'::jsonb, 0, '{"strategy": "aimed at increasing, drawn praise and criticism = מטרה + תגובות מעורבות.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["נכון! אותה משמעות בדיוק: נועדה להגביר גיוון, קיבלה תגובות מעורבות", "סותר את קיום המדיניות שתוארה", "הפוך — סותר ''has drawn both praise and criticism''", "הפוך — ''reduce diversity'' סותר ''increasing diversity''"]}', 1.05, -1.0, 0.25, 2, 'ai', NULL, true),
('feddfd3e-c1a6-4e5d-b291-582b94f7ade2', 'restatement', 'The novel, translated into over twenty languages, has achieved remarkable international success.', NULL, '[{"id": "d", "text": "The novel has never been translated into any language."}, {"id": "b", "text": "Having been translated into more than twenty languages, the novel has become a major international success."}, {"id": "c", "text": "The novel failed completely both nationally and internationally."}, {"id": "a", "text": "The novel is only popular in its country of origin."}]'::jsonb, 1, '{"strategy": "translated into over twenty languages, achieved success = פרטים תומכים בהצלחה.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["הפוך — סותר ''translated into over twenty languages''", "נכון! אותה משמעות בדיוק: תורגם ליותר מ-20 שפות, הצלחה בין-לאומית גדולה", "הפוך — סותר ''achieved remarkable international success''", "הפוך — סותר ''international success''"]}', 1.06, -1.0, 0.25, 2, 'ai', NULL, true),
('7231c683-4d48-4c01-b319-2494bb30eaca', 'restatement', 'The workers, having completed the project ahead of schedule, received a bonus from management.', NULL, '[{"id": "a", "text": "Management refused to give any bonuses."}, {"id": "c", "text": "The workers never completed the project."}, {"id": "d", "text": "Because they finished the project earlier than planned, the workers were given a bonus."}, {"id": "b", "text": "The workers finished the project late and were penalized."}]'::jsonb, 2, '{"strategy": "having completed ahead of schedule, received bonus = סיבה-תוצאה.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["הפוך — סותר ''received a bonus from management''", "סותר ''having completed the project ahead of schedule''", "נכון! אותה משמעות בדיוק: סיימו מוקדם מהמתוכנן, קיבלו בונוס", "הפוך — ''late'' סותר ''ahead of schedule'', ''penalized'' סותר ''received a bonus''"]}', 0.95, -1.0, 0.25, 2, 'ai', NULL, true),
('c4e5f0a1-91b7-4fdd-8adc-f162535e5681', 'restatement', 'The restaurant, though recently opened, has already built a loyal customer base.', NULL, '[{"id": "c", "text": "The restaurant has no customers at all."}, {"id": "b", "text": "The restaurant closed shortly after opening."}, {"id": "d", "text": "The restaurant has been open for many years."}, {"id": "a", "text": "Despite having opened only recently, the restaurant has already gained devoted regular customers."}]'::jsonb, 3, '{"strategy": "though recently opened, already built loyal base = ניגוד זמן.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["הפוך — סותר ''has already built a loyal customer base''", "הפוך — סותר ''has already built a loyal customer base''", "הפוך — סותר ''recently opened''", "נכון! אותה משמעות בדיוק: נפתחה לאחרונה, אך כבר בנתה בסיס לקוחות נאמן"]}', 1.05, -1.0, 0.25, 2, 'ai', NULL, true),
('5d4d5335-d46e-4203-a660-f4cff4460aa1', 'restatement', 'The committee''s proposal, revised multiple times, finally gained unanimous approval.', NULL, '[{"id": "d", "text": "After being revised several times, the proposal eventually received approval from all committee members."}, {"id": "a", "text": "The proposal was rejected by everyone on the committee."}, {"id": "b", "text": "The proposal was approved without any revisions."}, {"id": "c", "text": "The committee never discussed any proposal."}]'::jsonb, 0, '{"strategy": "revised multiple times, finally gained unanimous approval = תהליך שהוביל להצלחה.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["נכון! אותה משמעות בדיוק: אחרי כמה תיקונים, קיבלה אישור מכל חברי הוועדה", "הפוך — סותר ''finally gained unanimous approval''", "הפוך — סותר ''revised multiple times''", "סותר את קיום ההצעה שתוארה"]}', 1.13, -1.0, 0.25, 2, 'ai', NULL, true),
('07538dde-3f13-41ef-a80c-eae4905d4ae1', 'restatement', 'The bridge, closed for repairs since last month, is expected to reopen within two weeks.', NULL, '[{"id": "c", "text": "The bridge will remain closed permanently."}, {"id": "b", "text": "Having been shut for repairs since last month, the bridge should reopen in about two weeks."}, {"id": "a", "text": "The bridge reopened over a year ago."}, {"id": "d", "text": "The bridge has never been closed for repairs."}]'::jsonb, 1, '{"strategy": "closed since last month, expected to reopen = מצב נוכחי + תחזית עתידית.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["הפוך — סותר ''is expected to reopen within two weeks''", "נכון! אותה משמעות בדיוק: סגור לתיקונים מהחודש שעבר, צפוי להיפתח מחדש בעוד שבועיים", "הפוך — סותר את התיאור הכרונולוגי", "הפוך — סותר ''closed for repairs since last month''"]}', 0.97, -1.0, 0.25, 2, 'ai', NULL, true),
