('7fcb0f4a-2ae9-494f-b993-3dfcde51e1c9', 'restatement', 'The volunteers, motivated by a shared sense of purpose, worked long hours without complaint.', NULL, '[{"id": "d", "text": "The volunteers complained constantly about their working hours."}, {"id": "b", "text": "The volunteers refused to work at all."}, {"id": "c", "text": "No one had any particular motivation for volunteering."}, {"id": "a", "text": "Driven by a common sense of purpose, the volunteers put in long hours willingly."}]'::jsonb, 3, '{"strategy": "motivated by shared purpose, worked without complaint = סיבה-תוצאה.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["הפוך — סותר ''without complaint''", "הפוך — סותר ''worked long hours''", "סותר ''motivated by a shared sense of purpose''", "נכון! אותה משמעות בדיוק: מונעים ממטרה משותפת, עבדו שעות ארוכות ברצון"]}', 0.91, -1.0, 0.25, 2, 'ai', NULL, true),
